import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

export default function AdminLogin() {
  const [key, setKey] = useState('');
  const navigate = useNavigate();

  function submit(e) {
    e.preventDefault();
    if (!key) return;
    localStorage.setItem('admin_key', key);
    navigate('/admin/dashboard');
  }

  return (
    <div className="container card" style={{ maxWidth: 640, margin: '24px auto', padding: 20 }}>
      <h2>Admin Login</h2>
      <form onSubmit={submit}>
        <label>Admin Key</label>
        <input className="input" value={key} onChange={(e) => setKey(e.target.value)} placeholder="Enter admin key" />
        <div style={{ marginTop: 12 }}>
          <button className="btn" type="submit">Enter Admin</button>
        </div>
      </form>
    </div>
  );
}
